  "faq.freePlay": "ᑭᒍᓯᒃ ᐅᓪᓗᒋᐊᖅᑐᖏᓐᓂᖅ?",
  "faq.n07Questions": "07 · ᐱᔪᓐᓇᐅᑎᑦ",
  "faq.notYetLan": "ᓱᓕ ᐊᖏᓚᖅ. LAN ᑲᑎᒪᔪᑦ ᐱᖅᑯᕐᓂᖅ ᑕᒪᓐᓇ ᓄᓇᒥ ᐅᓪᓗᒥ ᐊᑐᖅᑐᖅ (0.2.0-ᒥᑦ); ᓯᓚᑦᑖᓂ ᐱᖅᑯᕐᓂᖅ ᓴᓇᖅᑕᐅᖏᓚᖅ.",
  "faq.prototypeWasBuilt": "ᓯᕗᓪᓕᖅ ᑎᑎᕋᕐᕕᒃ Quake III Arena (GPL) ᑎᑎᕋᕐᕕᒥᑦ ᓴᓇᖅᑕᐅᔪᖅ ᐊᒻᒪᓗ Elite Dangerous ᐅᒥᐊᕐᔪᐃᑦ ᓇᓗᓇᐃᖅᑯᑎᒥᑦ. ᐅᓪᓗ ᑕᒡᕙ ᑲᐃᒻ ᑎᑎᕋᕐᕕᒃ BuB-ᒧᑦ ᓄᖅᑲᖅᑐᖅ, ᓄᑖᖅ ᑎᑎᕋᕐᕕᒃ Claude Code-ᒥᑦ ᑎᑎᖃᖅᑕᐅᔪᖅ; ᑲᐃᒻ ᐊᕕᒃᑲᓐᓂᖅ ᓯᕗᓪᓕᖅ ᑎᑎᕋᕐᕕᒥᑦ ᐅᑎᖅᑎᓯᒪᔪᑦ ᐊᒻᒪᓗ ᐊᓯᐅᖅᑕᐅᔪᑦ. 0.3.0 ᑭᐅᑦᑕᐅᔪᖅ ᑕᒪᒃᑯᐊ 16 ᐅᒥᐊᕐᔪᒃ ᐊᓯᔾᔨᑦ ᓄᑖᓂᒃ ᕼᐊᓪᓂᒃ ᑐᓂᓯᓚᐅᖅᑐᖅ. ᑲᔪᓯᑎᑦᑎᓂᖅ ᕿᓂᒋᐊᖅᑕᐅᔪᖅ ᑎᑎᕋᕐᕕᒃ ᓇᓂᒃ GPL ᓯᕗᓪᓕᖅ ᑎᑎᕋᕐᕕᒥᑦ ᐅᑎᖅᑎᓯᒪᔪᖅ ᑕᒪᒃᑯᓄᖓ ᐊᒻᒪᓗ ᓯᕗᓪᓕᖅ ᐅᒥᐊᕐᔪᒃ ᓴᓇᖅᑕᐅᑎᑦ ᓇᓗᓇᐃᖅᑯᑎᒥᑦ ᐊᔾᔨᒌᓐᓂᖅ ᕿᓂᒋᐊᖅᑕᐅᔪᖅ. ᑎᑎᕋᕐᕕᒃ ᐊᔾᔨᒌᓐᓂᖅ ᕿᓂᕐᓂᖅ GPL ᓯᕗᓪᓕᖅ ᑎᑎᕋᕐᕕᒥᑦ <0/>-ᒥ ᓴᓇᖅᑕᐅᓚᐅᖅᑐᖅ, ᓇᓗᓇᐃᕈᓘᔭᖅᑕᐅᔪᑦ ᕿᓂᒋᐊᖅᑕᐅᔪᑦ. ᑭᓯᐊᓂ ᐅᑎᖅᑎᓯᒪᔪᖅ ᐊᓯᐅᖅᑕᐅᓂᐊᖅᑐᖅ ᐅᕙᓗ ᑎᑎᕋᖅᑕᐅᓂᐊᖅᑐᖅ. ᕿᓂᒋᐊᖅᑕᐅᓂᖅ ᓄᖑᓯᒪᖏᓐᓂᖅ ᑭᓯᐊᓂ, ᑭᐅᓂᖅ ᐊᖏᓚᖅ ᐅᖃᕐᓂᖅ ᐊᔾᔨᒌᖏᓚᖅ.",
  "faq.questions": "ᐱᔪᓐᓇᐅᑎᑦ",
  "faq.shipsArtInterface": "ᐅᒥᐊᕐᔪᐃᑦ, ᐊᔾᔨᒋᔭᑦ, ᑕᑯᔭᐅᑎ ᐊᒻᒪᓗ ᐊᓯᖏᑦ, ᑭᒍᓯᒃ ᐱᔭᕇᖅᑎᓗᓂ. <0>ᑎᑎᕋᐅᑎ ᑕᒪᓐᓇ ᑎᑎᕋᕐᕕᒥ<\/0> ᑕᒪᒃᑯᐊ ᐊᑐᕐᓂᖅ ᑎᑎᖃᖅᑕᐅᔪᖅ ᐊᒻᒪᓗ ᐊᓯᐅᖅᑎᓂᖅ ᐊᒻᒪᓗ ᑎᑎᖃᖅᑎ ᑕᑯᔭᐅᓂᐊᖅᑐᖅ.",
  "faq.shipsUpgradesPlanned": "ᐅᒥᐊᕐᔪᐃᑦ ᐊᒻᒪᓗ ᐊᓯᐅᖅᑎᓂᖅ ᓴᓇᓂᐊᖅᑐᑦ ᐱᖅᑯᕐᓂᖅ-ᒥᑦ ᐱᔭᕇᖅᑕᐅᔪᑦ ᐅᕙᓗ ᓂᐅᕕᖅᑕᐅᔪᑦ. ᑭᒍᓯᒃ ᐅᓪᓗᒋᐊᖅᑕᐅᔪᑦ ᐅᒥᐊᕐᔪᐃᑦ ᖃᓄᐃᓕᒻᒪᑦ ᐊᔾᔨᒌᓐᓂᖅ ᐃᓄᒃ-ᒥᑦ ᐃᓄᒃ-ᒧᑦ ᐱᖅᑯᕐᓂᖅ ᓱᓕ ᓴᓇᖅᑕᐅᓯᒪᔪᖅ.",
  "faq.thatPlanFree": "ᑖᒃᑯᐊ ᓴᓇᓂᖅ: ᑭᒍᓯᒃ ᐅᓪᓗᒋᐊᖅᑐᖏᓐᓂᖅ ᑲᐃᒻ ᑭᒍᓯᒃ ᐊᒻᒪᓗ ᐃᓚᖏᑦ ᑭᓯᐊᓂ ᐊᑐᕐᓂᖅ. ᓴᓇᖅᑕᐅᖏᓚᖅ ᓱᓕ.",
  "faq.wasAnyoneS": "ᐃᓄᒃ ᓴᓇᖅᑕᐅᔪᖅ ᐊᔾᔨᒋᔭᐅᓚᐅᖅᑐᖅ?",
  "faq.whenOutWhat": "ᓯᕗᓪᓕᖅ ᓇᖏᓚᖅ ᐊᒻᒪᓗ ᑭᓱᒥ?",
  "faq.whichPartsWill": "ᑭᓯ ᐃᓄᑦ ᐊᓯᐅᖅᑎᓂᐊᖅᑐᑦ, ᐊᒻᒪᓗ ᖃᓄᐃᓕᒻᒪᑦ ᐅᕙᑦᑎᓐᓂᒃ ᓇᓗᓇᐃᖅᑐᖅ?",
  "faq.whyWouldAi": "ᑭᓯ AI-ᒥᑦ ᓴᓇᖅᑕᐅᔪᖅ ᑲᐃᒻ ᑎᑎᖃᖅᑎᓄᑦ ᐃᑲᔪᖅᑐᖅ?",
  "faq.willPayWin": "ᑭᒍᓯᒃ ᐅᓪᓗᑎᓪᓗ ᐊᑐᕐᓂᖅ?",
  "faq.windowsPcThere": "Windows PC. ᓯᕗᓪᓕᖅ ᓇᖏᓚᖅ ᐊᒻᒪᓗ ᑭᒍᓯᒃ ᐊᑭᓕᐅᖏᓚᖅ ᓱᓕ.",
  "footer.anthropicClaudeClaude": "Anthropic, Claude ᐊᒻᒪᓗ Claude Code ᓇᓗᓇᐃᖅᑯᑎᑦ Anthropic, PBC-ᒥᑦ. Unreal Engine ᐊᒻᒪᓗ Epic Games ᓇᓗᓇᐃᖅᑯᑎᑦ Epic Games, Inc.-ᒥᑦ. Blender ᓇᓗᓇᐃᖅᑯᑎ Blender Foundation-ᒥᑦ. Quake III Arena ᐊᒻᒪᓗ Elite Dangerous ᓇᓗᓇᐃᖅᑯᑎᑦ ᓴᓇᔨᓄᑦ. ᑕᒪᒃᑯᐊ ᐊᑎᑦ ᓴᓇᔨᓄᑦ ᐊᒻᒪᓗ ᐊᑐᖅᑐᑦ ᑭᓯᐊᓂ ᓇᓗᓇᐃᖅᓯᓗᓂ ᐱᓇᓱᒃᑎᓂᒃ. Orion-81 ᑖᒃᑯᓂᒃ ᐃᓚᖃᖏᓚᖅ, ᑲᒪᒋᔭᐅᖏᓚᖅ ᐅᕙᓗ ᑭᒍᓯᒃ ᐅᓪᓗᒋᐊᖅᑕᐅᖏᓚᖅ.",
  "footer.aspirationalNoPartnership": "ᑕᒪᓐᓇ ᐃᓱᒪᒋᔭᖅ ᑭᓯᐊᓂ. ᐃᓚᖃᕐᓂᖅ, ᑲᑎᒪᓂᖅ ᐅᕙᓗ ᑲᒪᒋᔭᐅᓂᖅ ᓇᖏᓚᖅ.",
  "footer.channelComing": "ᑕᑯᔭᐅᑎ ᐊᑏᑦᑕᐅᓂᐊᖅᑐᖅ",
  "footer.devlogYoutube": "YouTube-ᒥ ᑎᑎᕋᐅᑎ",
  "footer.followKickstarter": "Kickstarter ᑭᖑᓪᓕᖅ",
  "footer.futurePartners": "ᓯᕗᓂᒧᑦ ᐃᓚᖃᖅᑎ?",
  "footer.noTrackersNo": "ᑕᑯᓐᓇᖅᑎᑦ ᐃᓗᐊᓂᖏᓚᖅ. ᑯᑭᔅ ᐃᓗᐊᓂᖏᓚᖅ. ᑕᑯᔭᐅᖅ ᑎᑎᕋᕐᕕᒃ. ᑕᒪᒃᑯᐊ ᐊᑐᕐᓂᖅ ᑎᑎᕋᕐᕕᒥᑦ ᓇᓗᓇᐃᖅᑕᐅᔪᑦ; ᑕᕝᕙᓂ ᐊᑭᓕᐅᓂᖅ ᐅᕙᓗ ᐅᖃᐅᓯᕐᓂᖅ ᐃᓗᐊᓂᖏᓚᖅ.",
  "footer.notLiveYet": "ᑕᑯᔭᐅᕙᓪᓗᐊᖏᓚᖅ",
